<?php $this->load->view('frontend/evaluation_header');
$thai_months=array(1=>'มกราคม',2=>'กุมภาพันธ์',3=>'มีนาคม',4=>'เมษายน',5=>'พฤษภาคม',6=>'มิถุนายน',7=>'กรกฎาคม',8=>'สิงหาคม',9=>'กันยายน',10=>'ตุลาคม',11=>'พฤศจิกายน',12=>'ธันวาคม');
$thai_date=function($value,$with_time=FALSE)use($thai_months){$time=strtotime((string)$value);if(!$time)return '-';$text=(int)date('j',$time).' '.$thai_months[(int)date('n',$time)].' '.((int)date('Y',$time)+543);if($with_time)$text.=' เวลา '.date('H:i',$time).' น.';return $text;}; ?>
<div class="card eval-card"><div class="card-body p-4 p-md-5"><span class="badge text-bg-primary mb-2"><?= html_escape($assignment->batch_no) ?></span><h1 class="h3"><?= html_escape($assignment->survey_title) ?></h1><p class="lead mb-1"><?= html_escape($assignment->course_title) ?></p><p class="text-secondary mb-1">วันอบรม: <?= html_escape($thai_date($assignment->start_date)) ?><?php if(!empty($assignment->end_date)&&$assignment->end_date!==$assignment->start_date): ?> – <?= html_escape($thai_date($assignment->end_date)) ?><?php endif; ?></p><p class="small text-secondary">ช่วงเวลาตอบ: <?= html_escape($thai_date($assignment->open_at,TRUE)) ?> – <?= html_escape($thai_date($assignment->close_at,TRUE)) ?></p>
<?php if($state==='upcoming'): ?><div class="alert alert-info">แบบประเมินจะเปิดวันที่ <?= html_escape($thai_date($assignment->open_at,TRUE)) ?></div><?php else: ?><?php if($state==='closed'): ?><div class="alert alert-secondary">แบบประเมินปิดรับคำตอบแล้ว ผู้ที่ดำเนินการครบสามารถค้นหารายชื่อเพื่อดูสถานะและดาวน์โหลดวุฒิบัตรได้</div><?php endif; ?>
<hr><h2 class="h5 mt-4">ค้นหารายชื่อของคุณ</h2><p class="text-secondary">กรอกชื่อ นามสกุล หรือบางส่วนของอีเมลอย่างน้อย 2 ตัวอักษร</p><form method="post"><input type="hidden" name="action" value="search"><div class="input-group input-group-lg"><input class="form-control" name="q" required minlength="2" value="<?= html_escape($this->input->post('q',TRUE)) ?>" placeholder="เช่น สมชาย หรือ somchai"><button class="btn btn-primary">ค้นหา</button></div></form>
<?php if($this->input->method(TRUE)==='POST'): ?><div class="mt-4"><?php if(!$results): ?><div class="alert alert-warning">ไม่พบรายชื่อ กรุณาตรวจสอบคำค้นหาหรือติดต่อเจ้าหน้าที่</div><?php endif; foreach($results as $r): ?><div class="border rounded-3 p-3 mb-2 d-flex align-items-center justify-content-between gap-2"><div><strong><?= html_escape($r->first_name.' '.$r->last_name) ?></strong><small class="d-block text-secondary"><?= html_escape($r->masked_email) ?></small></div><a class="btn btn-outline-primary" href="<?= site_url('evaluation/'.$assignment->public_code.'/verify/'.$r->invitation_id) ?>">นี่คือฉัน</a></div><?php endforeach; ?></div><?php endif; ?>
<?php endif; ?></div></div>
